def pad_to_multiple(s, multiple, ch):
    if multiple <= 0:
        return s
    remainder = len(s) % multiple
    if remainder == 0:
        return s
    return s + ch * (multiple - remainder)

def center_text_block(lines, width):
    result = []
    for s in lines:
        if len(s) >= width:
            result.append(s)
        else:
            total = width - len(s)
            left = total // 2
            right = total - left
            result.append(' ' * left + s + ' ' * right)
    return result

def wrap_text(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return lines

def justify_line(words, width):
    if len(words) == 1:
        return words[0].ljust(width)
    total_chars = sum(len(w) for w in words)
    total_spaces = width - total_chars
    gaps = len(words) - 1
    base, extra = divmod(total_spaces, gaps)
    line = ''
    for i, w in enumerate(words[:-1]):
        line += w + ' ' * (base + (1 if i < extra else 0))
    line += words[-1]
    return line

def wrap_and_count(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return len(lines)

def column_layout(items, ncols, width):
    rows = []
    for i in range(0, len(items), ncols):
        chunk = items[i:i + ncols]
        rows.append(' '.join(c.ljust(width) for c in chunk))
    return rows

def truncate_column(s, width):
    if len(s) > width:
        return s[:width]
    return s.ljust(width)

def truncate_ellipsis(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    return s[:maxlen - 3] + '...'

def truncate_words_ellipsis(s, maxwords):
    words = s.split()
    if len(words) <= maxwords:
        return ' '.join(words)
    return ' '.join(words[:maxwords]) + '...'
